/* ---------- AI Surprise story (in-browser WebLLM, keyless) ---------- */
const AI_MODEL='Qwen2.5-1.5B-Instruct-q4f16_1-MLC',AI_MB='~1 GB';
const KID_BAN=/\b(ghosts?|haunt\w*|horror|blood\w*|kill\w*|dead|death|die[sd]?|dying|monsters?|demons?|zombies?|skulls?|weapons?|guns?|knife|knives|scream\w*|terrif\w*|nightmares?|devil|witch(es)?|creepy|spooky|evil|murder\w*|corpse|grave(yard)?s?)\b/i;
const SPARKS=['a map that only appears in moonlight','a lost button that wants to go home','a cloud that hums','a door no bigger than a teacup','a tiny lighthouse','a library on the back of a turtle','a firefly who forgot how to glow','a bridge made of rainbows','a sleepy comet','a picnic at midnight','a whispering seashell','a kite that pulls towards the stars','a lantern festival','a river of warm milk','a snow globe that opens','a choir of crickets'];
const ASPARK=['a letter found in an old coat','a train that runs only after midnight','a garden kept by a stranger','an old radio playing a song from long ago','a lighthouse keeper\'s logbook','a rowing boat on a mirror-still lake','an inn at the edge of the map','a key with no lock','a late-night bookshop','a clock that runs slow','a field of night-blooming flowers','a candle that never burns down'];
var AID=null,ENG=null,ENGP=null;
async function hasGPU(){try{return !!(navigator.gpu&&await navigator.gpu.requestAdapter())}catch{return false}}
function aiStop(){try{ENG&&ENG.interruptGenerate()}catch{}if(AID)AID.stop=true}
function aiStart(f){if(!f)return;const v=Object.fromEntries(new FormData(f)),u=me(),adult=f.dataset.form==='astory';
 const prof=adult?u.listeners.find(x=>x.id===v.lid):u.children.find(x=>x.id===v.cid);if(!prof)return;
 const opt=adult?{mode:'adult',genre:AGEN[v.genre]?v.genre:'nature',mood:v.mood,length:5}:{mode:'kids',topic:KTOP[v.topic]?v.topic:(Story.matchTopic(prof.interests)||Object.keys(KTOP).filter(k=>k!=='bible'&&k!=='holidays')[Math.floor(Math.random()*15)]),lesson:v.lesson,length:5,friend:(v.friend||'').trim().slice(0,40)};
 opt.prof=prof;aiRun(opt)}
function prompts(o){const p=o.prof,r=Math.random;if(o.mode==='adult'){const sp=ASPARK[Math.floor(r()*ASPARK.length)];
  return{sys:`You are a gentle sleep-story narrator for adults. Write slow, calming, beautifully descriptive bedtime stories in second person ("you"). The genre is strictly: ${AGEN[o.genre]}. Keep it soothing: no gore, no shocks, no cliffhangers. ${o.genre==='ghost'?'Ghost stories must be atmospheric and comforting, never frightening or violent. ':''}${o.genre==='bible'||o.genre==='history'?'Stay faithful to the well-known story or historical facts; do not invent quotations. ':''}Write in plain prose paragraphs separated by blank lines. No headings, no lists, no markdown. Occasionally invite the listener to breathe slowly. End by guiding the listener gently into sleep.`,
  user:`Write a brand-new ${AGEN[o.genre]} sleep story of about 700 words for ${p.name}${p.interests?`, who enjoys ${p.interests}`:''}. Mood: ${o.mood||'calm'}. Include this element somewhere: ${sp}. Put the title on the first line as "Title: ..." and then the story.`}}
 const age=+p.age||5,lesson=o.lesson||'kindness';const sp=SPARKS[Math.floor(r()*SPARKS.length)];
 return{sys:`You are a warm children's bedtime storyteller. Write gentle, age-appropriate stories for a ${age}-year-old, with ${age<=5?'very simple words and short sentences':'simple, vivid language'}. Strictly no scary content: no ghosts, monsters, villains, violence, injury, death, danger or nightmares. Keep everything cosy, kind and safe. Write in plain paragraphs separated by blank lines. No headings, no lists, no markdown. Include some dialogue and sensory details. End with the child calm, safe in bed and drifting off to sleep.`,
  user:`Write a brand-new bedtime story of about 700 words. Topic (stay strictly on it): ${KTOP[o.topic]}. Hero: ${p.name}, age ${age}${p.pronoun&&p.pronoun!=='they'?` (${p.pronoun==='he'?'a boy':'a girl'})`:''}, who loves ${p.interests||'adventures'}. Sidekick: a friendly ${p.animal||'bunny'}.${o.friend?` Also bring along: ${o.friend}.`:''} Gentle lesson: ${lesson}. Include: ${sp}. Shape: cosy opening, a journey, two or three small encounters, a gentle challenge solved with ${lesson}, a happy resolution, then a slow, sleepy wind-down. Put the title on the first line as "Title: ..." and then the story.`}}
function clean(o,txt){let t=txt.replace(/[*#_`]+/g,'');if(o.mode!=='adult')t=t.split(/(?<=[.!?])\s+/).filter(s=>!KID_BAN.test(s)).join(' ').replace(/ ?\n ?/g,'\n');return t}
function parseAI(o,txt){let title='',body=clean(o,txt);const m=body.match(/^\s*Title:\s*(.+)\n/i);if(m){title=m[1].trim().replace(/^["“]|["”]$/g,'');body=body.slice(m[0].length)}
 const paras=body.split(/\n\s*\n|\n/).map(s=>s.trim()).filter(Boolean);return{title:title||(o.mode==='adult'?'A Quiet Night':`${o.prof.name}'s Surprise Story`),paras}}
function renderAI(){const A=$('#app'),o=AID.opt,{title,paras}=parseAI(o,AID.text);const w=AID.text.split(/\s+/).filter(Boolean).length,done=AID.done;
 A.innerHTML=`<div class="card"><span class="badge ${AID.kind==='ai'?'gold':''}">${AID.kind==='ai'?'✨ AI story':'🔀 Remix (template engine, not AI)'}</span> <span class="tag">${esc(o.mode==='adult'?AGEN[o.genre]:KTOP[o.topic])}</span>
 ${AID.note?`<p class="muted" style="font-size:13px">${esc(AID.note)}</p>`:''}
 <div id="aiprog" ${AID.prog==null?'hidden':''}><p class="muted">Downloading AI model (first time only, ${AI_MB}). It is cached in your browser for next time.</p><div class="bar"><i style="width:${Math.round((AID.prog||0)*100)}%"></i></div><p class="muted" id="aiptxt" style="font-size:12px">${esc(AID.ptxt||'')}</p></div>
 <h1 style="font-size:30px" id="aititle">${esc(title)}</h1><p class="muted" id="aimeta">${done?`⏱ About ${Math.max(1,Math.round(w/(o.mode==='adult'?113:130)))} minutes read aloud · ${w} words`:`Writing… ${w} words`}</p>
 <div id="aitext" class="aitext">${paras.map(p=>`<p class="page">${esc(p)}</p>`).join('')}${done?'':'<span class="caret"></span>'}</div>
 <div class="row" style="margin-top:14px">${done?`${AID.saved?`<a class="btn" href="#/story/${AID.saved}">Open in reader →</a>`:`<button class="btn" data-act="aisave">💾 Save to library</button>`}<button class="btn ghost" data-act="aiagain">✨ Try another</button>`:`<button class="btn ghost" data-act="aiagain" disabled>Writing…</button>`}<a href="#/app">← Back</a></div>
 ${done&&!AID.saved?'<p class="muted" style="font-size:13px">Not saved yet. Unsaved stories are discarded when you leave this page.</p>':''}</div>`}
var _rq=0;const reRender=()=>{if(_rq)return;_rq=requestAnimationFrame(()=>{_rq=0;if(location.hash==='#/ai'&&AID)renderAI()})};
async function engine(onp){if(ENG)return ENG;if(!ENGP)ENGP=(async()=>{const W=await import('https://esm.run/@mlc-ai/web-llm');ENG=await W.CreateMLCEngine(AI_MODEL,{initProgressCallback:onp});return ENG})();try{return await ENGP}catch(e){ENGP=null;throw e}}
async function aiRun(o){aiStop();const my={opt:o,text:'',done:false,saved:null,kind:'ai',prog:null};AID=my;location.hash!=='#/ai'?location.hash='#/ai':renderAI();
 if(!(await hasGPU()))return remix(my,'Your browser or device does not support WebGPU, which in-browser AI needs (try desktop Chrome or Edge). Here is a freshly remixed story from our template engine instead.');
 let E;try{E=await engine(p=>{if(AID!==my)return;my.prog=p.progress;my.ptxt=p.text;reRender()})}catch(e){return remix(my,'The AI model could not load on this device ('+String(e.message||e).slice(0,80)+'). Here is a freshly remixed template story instead.')}
 if(AID!==my)return;my.prog=null;const P=prompts(o);const msgs=[{role:'system',content:P.sys},{role:'user',content:P.user}];
 try{for(let round=0;round<3&&!my.stop;round++){const st=await E.chat.completions.create({messages:msgs,stream:true,temperature:.9,top_p:.95,max_tokens:1100});let part='';
   for await(const ch of st){if(my.stop||AID!==my)break;const d=ch.choices[0]?.delta?.content||'';part+=d;my.text+=d;reRender()}
   const w=my.text.split(/\s+/).length;if(w>=650||my.stop)break;msgs.push({role:'assistant',content:part},{role:'user',content:`Continue the same story seamlessly from where it stopped (no title, no recap) for about ${700-w} more words, then finish with a calm, sleepy ending.`});my.text+='\n\n'}
 }catch(e){if(!my.text.trim())return remix(my,'The AI had trouble writing this time, so here is a freshly remixed template story instead.')}
 if(AID!==my)return;my.done=true;renderAI()}
function remix(my,note){if(AID!==my)return;const o=my.opt;my.kind='remix';my.note=note;my.prog=null;
 const s=Story.generate({child:o.prof,...o,remix:true,seed:'remix'+Math.random()+Date.now()});my.tpl=s;my.text='Title: '+s.title+'\n'+s.pages.map(p=>p.text).join('\n\n');my.done=true;renderAI()}
function aiSave(){const u=me();if(!u||!AID||!AID.done)return;const o=AID.opt,{title,paras}=parseAI(o,AID.text);const tpl=AID.tpl||Story.generate({child:o.prof,...o,seed:'scene'});
 const s={id:rid(),cid:o.prof.id,cn:o.prof.name,fav:false,created:Date.now(),title,scene:tpl.scene,animal:tpl.animal,topic:o.topic,lesson:o.lesson,genre:o.genre,mood:o.mood,mode:o.mode,minutes:5,pages:AID.tpl?tpl.pages:paras.map((t,i)=>({text:t,scene:o.mode==='adult'?tpl.scene:(i===0||i===paras.length-1?'bedroom':tpl.scene)})),[AID.kind]:true};
 u.stories.unshift(s);save(u);AID.saved=s.id;renderAI()}
window.addEventListener('beforeunload',e=>{if(AID&&!AID.saved&&AID.text.trim()){e.preventDefault();e.returnValue=''}});
